import urllib.request
import json

# Check all Stack Exchange sites for HVAC
url = 'https://api.stackexchange.com/2.3/sites?pagesize=500'
try:
    with urllib.request.urlopen(url, timeout=10) as response:
        data = json.load(response)
        for site in data.get('items', []):
            if 'hvac' in site.get('api_site_parameter', '').lower() or 'heating' in site.get('name', '').lower() or 'cooling' in site.get('name', '').lower():
                print(f'{site["name"]}: {site["api_site_parameter"]}')
except Exception as e:
    print(f'Error: {e}')
